<?php require_once __DIR__.'/../../config/app.php';requireLogin();$pageTitle='Employees';$pageSubtitle='Data Employees koperasi sekolah';$isAdmin=(authUser()['role']==='admin');$success=flash('success');$stmt=$pdo->query('SELECT * FROM employees ORDER BY employee_id DESC');$rows=$stmt->fetchAll(); ?>
<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Employees - Koperasi Sekolah</title><link rel="stylesheet" href="/styles/employees/index.css"></head><body><div class="layout"><?php require __DIR__.'/../../components/admin/sidebar.php';?><main class="main"><?php require __DIR__.'/../../components/admin/topbar.php';?><section class="content"><div class="toolbar"><div class="page-heading"><h2>Data Employees</h2><p>Daftar employees koperasi sekolah.</p></div><?php if($isAdmin):?><a class="btn btn-primary" href="create.php">+ Tambah Employee</a><?php endif?></div><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif?><div class="card"><table><thead><tr><th>Nomor Karyawan</th><th>Nama Lengkap</th><th>Jenis Kelamin</th><th>Tanggal Lahir</th><th>Jabatan</th><th>Gaji</th><?php if($isAdmin):?><th>Aksi</th><?php endif?></tr></thead><tbody><?php if(!$rows):?><tr><td class="empty" colspan="7">Belum ada data employees.</td></tr><?php else:foreach($rows as $row):?><tr><td><?= e($row['employee_number']) ?></td><td><?= e($row['full_name']) ?></td><td><?= e($row['gender']) ?></td><td><?= e($row['birth_date']) ?></td><td><?= e($row['position']) ?></td><td><?= e($row['salary']) ?></td><?php if($isAdmin):?><td class="actions"><a href="edit.php?id=<?= (int)$row['employee_id'] ?>">Edit</a><a class="delete" href="/actions/employees/destroy.php?id=<?= (int)$row['employee_id'] ?>" onclick="return confirm('Yakin ingin menghapus data ini?')">Hapus</a></td><?php endif?></tr><?php endforeach;endif?></tbody></table></div></section></main></div></body></html>